async def start_drkg(body: DrkgRequest):
    """Stage 3: match the research run's target genes to DrugBank compounds in DRKG. No LLM calls."""
    report = (await get_run(body.research_run_id))["report"]
    if not report or "profiles" not in report:
        raise HTTPException(409, "that research run hasn't produced a report yet")
    run_id = time.strftime("d%Y%m%d-%H%M%S-") + uuid.uuid4().hex[:6]
    run = RUNS[run_id] = Run(run_id=run_id, question="drkg matching", patient_id=report.get("patient_id", DEFAULT_PATIENT))
    asyncio.create_task(execute_drkg(run, report))
